     && /tmp/b2436-head-target/release/jackioh classify --base "$BASE" --parent-bin /tmp/b2436-base-target/release/jackioh --json > /tmp/b2436-classify.json)
   jq -r '.cards | join(",")' /tmp/b2436-classify.json; jq '.rule' /tmp/b2436-classify.json
   ```
